import pandas as pd
import numpy as np
import json

# Load data and charts
df = pd.read_csv('/app/benchmark/data.csv')
with open('/app/output/charts_data.json') as f:
    charts = json.load(f)

# ============================================================
# PRE-COMPUTE ALL KEY STATISTICS
# ============================================================

# Executive KPIs
overall_avg_ai_risk = df['ai_risk_score'].mean()
overall_median_salary = df['salary'].median()
overall_avg_skill_demand = df['skill_demand_score'].mean()
job_survival_rate = (df['job_survival_class'] >= 1).mean() * 100
ai_risk_2015 = df[df['year'] == 2015]['ai_risk_score'].mean()
ai_risk_2035 = df[df['year'] == 2035]['ai_risk_score'].mean()
ai_risk_growth = ((ai_risk_2035 - ai_risk_2015) / ai_risk_2015) * 100
salary_2015 = df[df['year'] == 2015]['salary'].median()
salary_2035 = df[df['year'] == 2035]['salary'].median()
salary_growth = ((salary_2035 - salary_2015) / salary_2015) * 100
survival_2015 = (df[df['year'] == 2015]['job_survival_class'] >= 1).mean() * 100
survival_2035 = (df[df['year'] == 2035]['job_survival_class'] >= 1).mean() * 100

# Automation Risk
risk_by_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False)
highest_risk_job = risk_by_job.index[0]
highest_risk_score = risk_by_job.iloc[0]
lowest_risk_job = risk_by_job.index[-1]
lowest_risk_score = risk_by_job.iloc[-1]

risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False)
highest_risk_country = risk_by_country.index[0]
lowest_risk_country = risk_by_country.index[-1]

high_risk_pct = (df['ai_risk_category'] == 'High Risk').mean() * 100
medium_risk_pct = (df['ai_risk_category'] == 'Medium Risk').mean() * 100
low_risk_pct = (df['ai_risk_category'] == 'Low Risk').mean() * 100

# Salary
salary_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False)
top_salary_country = salary_by_country.index[0]
top_salary_value = salary_by_country.iloc[0]
bottom_salary_country = salary_by_country.index[-1]
bottom_salary_value = salary_by_country.iloc[-1]

salary_by_job = df.groupby('job_title')['salary'].median().sort_values(ascending=False)
top_salary_job = salary_by_job.index[0]
top_salary_job_value = salary_by_job.iloc[0]
bottom_salary_job = salary_by_job.index[-1]
bottom_salary_job_value = salary_by_job.iloc[-1]

salary_by_exp = df.groupby('experience_level')['salary'].median().sort_values(ascending=False)
salary_by_edu = df.groupby('education_level')['salary'].median().sort_values(ascending=False)

salary_risk_corr = df['salary'].corr(df['ai_risk_score'])
salary_high_risk = df[df['ai_risk_category'] == 'High Risk']['salary'].median()
salary_low_risk = df[df['ai_risk_category'] == 'Low Risk']['salary'].median()
salary_risk_gap = ((salary_low_risk - salary_high_risk) / salary_high_risk) * 100

# Skills
skill_demand = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False)
top_skill = skill_demand.index[0]
top_skill_score = skill_demand.iloc[0]

skill_2015 = df[df['year'] == 2015].groupby('primary_skill')['skill_demand_score'].mean()
skill_2035 = df[df['year'] == 2035].groupby('primary_skill')['skill_demand_score'].mean()
skill_growth = ((skill_2035 - skill_2015) / skill_2015 * 100).sort_values(ascending=False)
fastest_growing_skill = skill_growth.index[0]
fastest_growth_pct = skill_growth.iloc[0]

# Job Survival
survival_by_job = df.groupby('job_title').apply(lambda x: (x['job_survival_class'] >= 1).mean() * 100, include_groups=False).sort_values(ascending=False)
best_survival_job = survival_by_job.index[0]
worst_survival_job = survival_by_job.index[-1]
worst_survival_rate = survival_by_job.iloc[-1]

survival_by_country = df.groupby('country').apply(lambda x: (x['job_survival_class'] >= 1).mean() * 100, include_groups=False).sort_values(ascending=False)
best_survival_country = survival_by_country.index[0]
worst_survival_country = survival_by_country.index[-1]

# Job openings
openings_by_job_2015 = df[df['year'] == 2015].groupby('job_title')['job_openings'].sum()
openings_by_job_2035 = df[df['year'] == 2035].groupby('job_title')['job_openings'].sum()
openings_growth = ((openings_by_job_2035 - openings_by_job_2015) / openings_by_job_2015 * 100).sort_values(ascending=False)
fastest_growing_openings_job = openings_growth.index[0]
fastest_openings_growth = openings_growth.iloc[0]

# Risk growth by job
risk_job_2015 = df[df['year'] == 2015].groupby('job_title')['ai_risk_score'].mean()
risk_job_2035 = df[df['year'] == 2035].groupby('job_title')['ai_risk_score'].mean()
risk_job_growth = ((risk_job_2035 - risk_job_2015) / risk_job_2015 * 100).sort_values(ascending=False)
fastest_risk_growth_job = risk_job_growth.index[0]
fastest_risk_growth_pct = risk_job_growth.iloc[0]

# Top combo for survival
best_combo = df.groupby(['job_title', 'country', 'education_level']).apply(lambda x: (x['job_survival_class'] >= 1).mean() * 100, include_groups=False).sort_values(ascending=False)
best_combo_str = f"{best_combo.index[0][0]} in {best_combo.index[0][1]} with {best_combo.index[0][2]}"

# ============================================================
